onStopSending(_msgId, status, _msg, _file) {
  if (status == Cr.NS_OK) {
    this._resolve();
  } else {
    this._reject(new Error(status));
  }
}

onSendNotPerformed(_msgId, status) {
  if (status == Cr.NS_OK) {
    this._resolve();
  } else {
    this._reject(new Error(status));
  }
}

onTransportSecurityError(_msgId, status, _secInfo, _location) {
  this._reject(new Error(status));
}

get promise() {
  return this._promise;
}
